import "./CaseSummary.css";

// A short case write-up from the API (GET /rings/{id} -> summary): exact facts plus what the main signal can mean.
// The text is built by a template and hand-written meanings (ml/narrative.py); nothing here is generated by a model.
// Hidden when the API sends none (older or sample data).
export function CaseSummary({ summary }) {
  if (!summary) return null;
  return (
    <section className="case-summary" aria-label="Case summary">
      <h3>Case summary</h3>
      <p>{summary}</p>
    </section>
  );
}

const ROLES = [
  ["victim", "Likely victim"],
  ["collector", "Collector"],
  ["mule", "Mule"],
  ["cashout", "Cash-out"],
];

// What the node colours in the flow graph mean. Roles are estimated from position in the ring.
export function RoleLegend({ colors }) {
  return (
    <div className="role-legend" aria-label="Role colours">
      {ROLES.map(([role, name]) => (
        <span key={role} className="role-legend-item">
          <span className="role-dot" style={{ background: colors[role] }} />
          {name}
        </span>
      ))}
      <span className="role-legend-note">estimated roles · arrows show the direction of payments</span>
    </div>
  );
}
